 .../plugins/sqlite/ResourceScoreMaintainer.h  |  1 +
 src/service/plugins/sqlite/StatsPlugin.cpp    |  2 ++
 3 files changed, 25 insertions(+)

diff --git a/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp b/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
index 7ebb2c96..97b0ad56 100644
--- a/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
+++ b/src/service/plugins/sqlite/ResourceScoreMaintainer.cpp
@@ -17,6 +17,7 @@
 #include <utils/d_ptr_implementation.h>

 // Local
+#include "Database.h"
 #include "ResourceScoreCache.h"
 #include "StatsPlugin.h"

@@ -123,3 +124,24 @@ void ResourceScoreMaintainer::processResource(const QString &resource, const QSt

     d->processResourcesTimer.start();
 }
+
+void ResourceScoreMaintainer::cancelProcessing(const QString &activity, const QString &application, const QString &resourcePattern)
+{
+    const auto pattern = Common::starPatternToRegex(resourcePattern);
+
+    for (auto activityIt = d->scheduledResources.begin(); activityIt != d->scheduledResources.end(); ++activityIt) {
+        if (!activity.isEmpty() && activityIt.key() != activity) {
+            continue;
+        }
+
+        for (auto applicationIt = activityIt->begin(); applicationIt != activityIt->end(); ++applicationIt) {
+            if (!application.isEmpty() && applicationIt.key() != application) {
+                continue;
+            }
+
+            applicationIt->removeIf([&pattern](const QString &resource) {
+                return pattern.match(resource).hasMatch();
+            });
+        }
+    }
+}
diff --git a/src/service/plugins/sqlite/ResourceScoreMaintainer.h b/src/service/plugins/sqlite/ResourceScoreMaintainer.h
index b564cd77..415c351e 100644
--- a/src/service/plugins/sqlite/ResourceScoreMaintainer.h
+++ b/src/service/plugins/sqlite/ResourceScoreMaintainer.h
@@ -25,6 +25,7 @@ public:
