From 1661bbf388cc4a02a48292ebf6b29cded3a0cef6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 02:09:59 +0100
Subject: [PATCH] krecentdocument: Add removeFilesInDirectory()

Callers that need to drop every recent entry under a folder, such as an
encrypted vault being locked, had to parse recently-used.xbel by hand,
since recentUrls() skips files that no longer exist. Add a call for it.

CCBUG: 444393
---
 src/core/krecentdocument.cpp | 55 ++++++++++++++++++++++++++++++++++++
 src/core/krecentdocument.h   |  8 ++++++
 2 files changed, 63 insertions(+)

diff --git a/src/core/krecentdocument.cpp b/src/core/krecentdocument.cpp
index d90810b7a..967253030 100644
--- a/src/core/krecentdocument.cpp
+++ b/src/core/krecentdocument.cpp
@@ -688,6 +688,61 @@ void KRecentDocument::removeApplication(const QString &desktopEntryName)
     }
 }

+void KRecentDocument::removeFilesInDirectory(const QUrl &directory)
+{
+    QFile input(xbelPath());
+    if (!input.exists()) {
+        return;
+    }
+
+    // Won't help for GTK applications and whatnot, but we can be good citizens ourselves
+    QLockFile lockFile(xbelPath() + QLatin1String(".lock"));
+    lockFile.setStaleLockTime(0);
+    if (!lockFile.tryLock(100)) { // give it 100ms
+        qCWarning(KIO_CORE) << "Failed to lock recently used";
+        return;
+    }
+
+    if (!input.open(QIODevice::ReadOnly)) {
+        qCWarning(KIO_CORE) << "Failed to open existing recently used" << input.errorString();
+        return;
+    }
+
+    QDomDocument document;
+    document.setContent(&input);
+    input.close();
+
+    auto xbelTags = document.elementsByTagName(xbelTag);
+    if (xbelTags.length() != 1) {
+        qCWarning(KIO_CORE) << "Invalid Xbel file, missing xbel element";
+        return;
+    }
+    auto xbelElement = xbelTags.item(0);
+    auto bookmarkList = xbelElement.childNodes();
+
+    bool fileChanged = false;
+    for (int i = bookmarkList.length() - 1; i >= 0; --i) {
+        const auto node = bookmarkList.item(i);
+
+        const auto hrefValue = node.attributes().namedItem(hrefAttribute);
+        if (!hrefValue.isAttr() || hrefValue.nodeValue().isEmpty()) {
+            continue;
+        }
+
+        const QUrl hrefUrl = QUrl::fromEncoded(hrefValue.nodeValue().toLatin1());
+        if (directory.isParentOf(hrefUrl)) {
+            xbelElement.removeChild(node);
+            fileChanged = true;
+        }
+    }
+
+    if (fileChanged) {
+        if (!input.open(QIODevice::WriteOnly) || (input.write(document.toByteArray(2)) < 0)) {
+            qCWarning(KIO_CORE) << "Couldn't save bookmark file " << input.fileName();
+        }
+    }
+}
+
 void KRecentDocument::removeBookmarksModifiedSince(const QDateTime &since)
 {
     QFile input(xbelPath());
diff --git a/src/core/krecentdocument.h b/src/core/krecentdocument.h
index 5e4ac4def..1ec57c416 100644
--- a/src/core/krecentdocument.h
+++ b/src/core/krecentdocument.h
@@ -139,6 +139,14 @@ public:
      */
     static void removeBookmarksModifiedSince(const QDateTime &since);

+    /*!
+     * Remove the bookmarks of all files and folders inside \a directory,
+     * including its subfolders.
+     *
+     * \since 6.33
+     */
+    static void removeFilesInDirectory(const QUrl &directory);
+
     /*!
      * Clear the recent document menu of all entries.
      */
